const routeParts = location.pathname.split('/').filter(Boolean);
const localeIndex = routeParts.findIndex(part => part in {tr:1,en:1,ru:1});
const localizedRoute = localeIndex >= 0;
const baseParts = localizedRoute ? routeParts.slice(0,localeIndex) : routeParts.filter(part => part !== 'index.html' && part !== '404.html');
const sitePrefix = baseParts.length ? `/${baseParts.join('/')}` : '';
const sitePath = path => `${sitePrefix}${path}`;
const locale = localizedRoute ? routeParts[localeIndex] : 'tr';
const d = D[locale];
const pageParts = localizedRoute ? routeParts.slice(localeIndex+1) : routeParts.filter(part => part !== 'index.html' && part !== '404.html');
const pageSlug = pageParts[0] || '';
const page = d.pages[pageSlug] || (pageSlug === (locale==='tr'?'iletisim':locale==='en'?'contact':'kontakty') ? d.contactPage : null);
const isHome = !pageSlug;
const allLocaleHomes={tr:sitePath('/tr/'),en:sitePath('/en/'),ru:sitePath('/ru/')};
const pathFor=(loc,slug='')=>sitePath(`/${loc}/${slug?slug+'/':''}`);
const linkHome=(label)=>`<a href="${allLocaleHomes[locale]}">${label}</a>`;
const chat=(message)=>`https://wa.me/${PHONE}?text=${encodeURIComponent(message)}`;
